questionvariables.text:
/*Variables for the function definition*/
aa:rand_with_step(20,40,5);
bb:rand(20)+2;
func1:x^2/aa + bb/10;

cc:rand(5)+1;
dd:rand(3)+2;
func2:x/dd + cc;

ee:rand_with_step(15,30,5);
ff:rand_with_step(4,10,1);
func3:x^2/ee + x/ff + 1/10;

gg:rand_with_step(115,120,1);
hh:rand_with_step(15,20,1);
jj:rand(20);
func4:x^3/gg + x/hh + 1/jj;
func:rand([func1,func2, func3,func4]);
f(y) := ev(func, x=y);

/*Variables for rectangle definition*/
rect_num:rand([3,4,5]);
rect_width:rand([1,2]);
left_limit:rand(4)+1;   /*Lower bound*/
right_limit:left_limit + rect_num * rect_width; /*Upper bound*/
rect_left_x_coords: makelist(i,i,left_limit,right_limit-rect_width,rect_width); /*x-coords of left corners*/

/*Variables for bounding box*/
x_min:-1;
x_max:right_limit+1;
y_min:-1;
y_vals:makelist(f(i),i,x_min,x_max,0.1);
y_max:ceiling(last(sort(y_vals)));

/*List of y-values for rectangles*/
rect_top_y_coords_lowersum: makelist(f(i), i, left_limit, right_limit-rect_width, rect_width);
rect_top_y_coords_uppersum: makelist(f(i+rect_width), i, left_limit, right_limit-rect_width, rect_width);

/* Computer lower/upper sum and integral*/
ta1:decimalplaces(apply("+", rect_top_y_coords_lowersum)*rect_width,2);
ta2:decimalplaces(apply("+", rect_top_y_coords_uppersum)*rect_width,2);
ta3:decimalplaces(int(func,x,left_limit,right_limit),2);

/* Strings for typesetting step by step solution */
indices: makelist(i, i, 1, rect_num);
fxi_lower: makelist(sconcat("f(x_", i, ")"), i, 0, rect_num-1);
efxi_lower: makelist(rect_top_y_coords_lowersum[i], i, 1, rect_num);
sum_fxi_lower: simplode(fxi_lower, "+");
sum_efxi_lower: simplode(efxi_lower, "+");
fxi_upper: makelist(sconcat("f(x_", i, ")"), i, 1, rect_num);
efxi_upper: makelist(rect_top_y_coords_uppersum[i], i, 1, rect_num);
sum_fxi_upper: simplode(fxi_upper, "+");
sum_efxi_upper: simplode(efxi_upper, "+");
